 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    divider = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if divider is None or divider == 0:
        return out
    top = grid[0]
    bottom = grid[-1]
    shared = {c for c, value in enumerate(top) if value != 0 and c < len(bottom) and bottom[c] == value}
    for r in range(1, divider):
        for c in shared:
            if out[r][c] == 0:
                out[r][c] = 4
    return out
